-- ЕРН — реестр должностных лиц таможенных органов (ДЛТО)
-- Источник: ern_full.sql, выгрузка от 12.11.2026, 16:50:09
-- Собрано: 19.11.2026
-- Дисклеймер: данные синтетические, артефакты допустимы
--
-- 30 записей. Реестр накладывается на общий датасет (dataset.sql) по
-- person_id: там же адрес, СНИЛС, ИНН и родственные связи этих лиц.
-- Именно этот файл правится через /admin.
-- ============================================================

PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

DROP TABLE IF EXISTS official;

CREATE TABLE official (
    person_id           TEXT PRIMARY KEY,  -- ссылка на person.person_id
    last_name           TEXT NOT NULL,
    first_name          TEXT NOT NULL,
    middle_name         TEXT NOT NULL,
    full_name           TEXT NOT NULL,     -- «ФАМИЛИЯ ИМЯ ОТЧЕСТВО»
    position            TEXT NOT NULL,     -- должность
    customs_post        TEXT NOT NULL,     -- таможенный пост
    tab_number          TEXT NOT NULL,     -- табельный номер
    passport_series     TEXT NOT NULL,
    passport_number     TEXT NOT NULL,
    passport_issue_date TEXT,
    passport_dept_code  TEXT,
    passport_issued_by  TEXT,
    gender              TEXT,
    birth_date          TEXT,
    birth_place         TEXT,
    citizenship         TEXT,
    citizenship_codes   TEXT,
    snils               TEXT,
    inn                 TEXT,
    marital_status      TEXT,
    address             TEXT
);
CREATE INDEX idx_official_post ON official(customs_post);

